SELECT d.phone, d.recibe, EXISTS (SELECT 1 FROM contacts c JOIN conversations v ON v.contact_id = c.id JOIN messages m ON m.conversation_id = v.id WHERE c.phone = d.phone AND m.sender_type = 'customer' AND m.created_at > now() - interval '24 hours') AS ventana_abierta FROM (SELECT CASE WHEN $2 = 'admin' THEN (SELECT c.phone FROM contacts c JOIN contact_tags ct ON ct.contact_id = c.id JOIN tags t ON t.id = ct.tag_id WHERE lower(t.name) = 'admin' ORDER BY c.created_at LIMIT 1) ELSE (SELECT c.phone FROM conversations v JOIN contacts c ON c.id = v.contact_id WHERE v.id = $1::uuid) END AS phone, (SELECT CASE WHEN o.quoted_destination_amount IS NULL THEN NULL ELSE rtrim(rtrim(to_char(o.quoted_destination_amount, 'FM999,999,999,990.99'), '0'), '.') || ' ' || CASE (CASE WHEN lower(coalesce(o.delivery_method,'')) <> '' THEN lower(o.delivery_method) ELSE coalesce((SELECT b.beneficiary_type FROM remittance_beneficiaries b WHERE b.operation_id=o.id AND b.status='vigente' ORDER BY b.position LIMIT 1),'') END) WHEN 'zelle' THEN 'USD por Zelle' WHEN 'clasica' THEN 'USD de Clásica' WHEN 'tropical' THEN 'USD de Tropical' WHEN 'efectivo_usd' THEN 'USD en efectivo' WHEN 'cuban_card' THEN 'CUP' ELSE coalesce(o.destination_currency, '') END END FROM remittance_operations o WHERE o.id::text = $3 LIMIT 1) AS recibe) d;